contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, address caller, bool attempt) public payable {
        // Precondition: caller is not the owner, so the call must revert.
        require(caller != c.owner(), "caller must not be owner");
        require(address(this).balance >= 0, "no ether needed");

        uint256 beforeBalance = address(c).balance;
        bool reverted;
        // The test contract is the only caller to c; to test a non-owner caller, we cannot
        // change msg.sender directly. However, c.withdrawAll is always called by this test
        // contract, which is deployed as the owner only if _c.owner == address(this).
        // In this test, we will call withdrawAll via the test contract itself. If the test
        // contract is not the owner, the call reverts; if it is the owner, it succeeds.
        // To exercise both branches, we use the `attempt` parameter and the fact that
        // the constructor gives us a c whose owner is fixed. But to make a general rule
        // over all inputs, we can call withdrawAll and observe whether it reverts.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(address(c).balance == beforeBalance);
        } else {
            assert(address(c).balance == 0);
        }
    }

    receive() external payable {}
}

