    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function _run(address recipient) internal {
        vm.assume(msg.sender == address(this));
        vm.assume(recipient != address(c));
        uint256 beforeBalance = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
