contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address recipient) public payable {
        require(recipient != address(c));
        require(recipient != address(this));

        uint256 beforeBalance = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted ? address(c).balance == beforeBalance : (address(c).balance == 0 && recipient.balance == beforeRecipient + beforeBalance));
    }

    fallback() external payable {}
}
